    public Vector2[] rounded_polygon(Vector2[] points,double radius)
    {
        if(radius<=0||points.Length<3)return points;var result=new System.Collections.Generic.List<Vector2>();for(int index=0;index<points.Length;index++){var corner=points[index];var previous=points[(index-1+points.Length)%points.Length];var next=points[(index+1)%points.Length];float distance=(float)Math.Min(radius,Math.Min(corner.DistanceTo(previous),corner.DistanceTo(next))*.5);var start=corner.MoveToward(previous,distance);var end=corner.MoveToward(next,distance);for(int step=0;step<9;step++){float t=step/8f;var point=start*(1-t)*(1-t)+corner*2*t*(1-t)+end*t*t;if(result.Count==0||!result[^1].IsEqualApprox(point))result.Add(point);}}if(result.Count>1&&result[0].IsEqualApprox(result[^1]))result.RemoveAt(result.Count-1);return result.ToArray();
    }
    public Transform2D orientation(Resource layer)=>new(layer.Get("rotation").AsSingle(),Vector2.Zero);
    private static Vector2 Flip(Settings properties)=>new(Get(properties,"flip_x",false).AsBool()?-1:1,Get(properties,"flip_y",false).AsBool()?-1:1);
    public Transform2D local_transform(Resource layer)
