    }
    public void set_linear_basis(Resource layer,Transform2D basis){var properties=Properties(layer);var normalized=orientation(layer).AffineInverse()*basis.ScaledLocal(Flip(properties));properties["basis_x"]=normalized.X;properties["basis_y"]=normalized.Y;}
    public Vector2 content_dimensions(Resource layer)
    {
        var dimensions=layer.Get("dimensions").AsVector2();if(layer.Get("kind").AsString()!="text")return dimensions;var properties=Properties(layer);var schema=GD.Load<CSharpScript>("res://scripts/actors/core/ActorTextSettings.cs");var settings=schema.Call("values",Get(properties,"text_settings")).AsGodotDictionary();var font=schema.Call("font",settings).As<Font>();int size=Math.Max(1,Mathf.RoundToInt(Get(settings,"font_size",72).AsDouble()*Get(properties,"text_scale",1).AsDouble()));var measured=font.GetMultilineStringSize(Get(properties,"text","").AsString(),(HorizontalAlignment)Get(properties,"alignment",0).AsInt32(),dimensions.X,size);return dimensions.Max(measured+Vector2.One*(float)Get(settings,"outline_size",0).AsDouble()+Get(settings,"shadow_offset",Vector2.Zero).AsVector2().Abs());
    }
    public Resource copy_layer(Resource layer)
    {
        var copy=NewLayer();foreach(string key in new[]{"id","label","kind","parent_id","position","dimensions","rotation","visible","isolated","locked","opacity","blend","clip_to_below","texture","paint_base","mask"})copy.Set(key,layer.Get(key));var source=Properties(layer);var properties=source.Duplicate(true);copy.Set("properties",properties);var warp=layer.Get("warp").AsGodotObject();if(warp!=null)copy.Set("warp",warp.Call("copy_warp"));using var materials=new ImageMaterialResourceOperations();var live=copy.Get("live_paint").AsGodotArray();foreach(var region in layer.Get("live_paint").AsGodotArray())live.Add(materials.copy_region(region.As<Resource>()));if(IsScript(Get(source,"texture_recipe"),"res://Workspaces/ImageWorkspace/image_texture_recipe.gd")){using var recipes=new ImageProceduralTextureOperations();properties["texture_recipe"]=recipes.copy_recipe(source["texture_recipe"].As<Resource>());}if(IsScript(Get(source,"texture_material"),"res://Workspaces/ImageWorkspace/texture_material.gd"))properties["texture_material"]=materials.copy_material(source["texture_material"].As<Resource>());foreach(string key in new[]{"text_settings","noise_object"})if(IsScript(Get(source,key),"res://scripts/actors/core/actor_object_data.gd"))properties[key]=source[key].AsGodotObject().Call("copy_object");var effects=copy.Get("effects").AsGodotArray();foreach(var raw in layer.Get("effects").AsGodotArray().Duplicate(true)){var effect=raw.AsGodotDictionary();var curveValue=Get(effect,"curve");if(curveValue.VariantType==Variant.Type.Object&&curveValue.AsGodotObject() is Curve curve)effect["curve"]=curve.Duplicate();var curves=Get(effect,"curves",new Settings()).AsGodotDictionary();var keys=new System.Collections.Generic.List<Variant>(curves.Keys);foreach(var key in keys)if(curves[key].VariantType==Variant.Type.Object&&curves[key].AsGodotObject() is Curve channel)curves[key]=channel.Duplicate();effects.Add(effect);}return copy;
    }
    public void erase_live_paint(Resource layer,Image? eraser)
    {
        if(eraser==null||eraser.IsEmpty())return;foreach(var raw in layer.Get("live_paint").AsGodotArray()){var region=raw.As<Resource>();bool live=region.Get("template_id").AsString().Length>0;var source=region.Get(live?"coverage":"raster").As<Texture2D>();if(source==null)continue;using var original=source.GetImage();if(original==null||original.IsEmpty())continue;using var pixels=(Image)original.Duplicate();pixels.Convert(Image.Format.Rgba8);Image? resized=null;var mask=eraser;if(mask.GetSize()!=pixels.GetSize()){resized=(Image)mask.Duplicate();resized.Resize(pixels.GetWidth(),pixels.GetHeight(),Image.Interpolation.Bilinear);mask=resized;}try{var bounds=mask.GetUsedRect();for(int y=bounds.Position.Y;y<bounds.End.Y;y++)for(int x=bounds.Position.X;x<bounds.End.X;x++){float strength=mask.GetPixel(x,y).A;if(strength<=0)continue;var color=pixels.GetPixel(x,y);color.A*=1-strength;if(color.A<=0)color=Colors.Transparent;pixels.SetPixel(x,y,color);}region.Set(live?"coverage":"raster",ImageTexture.CreateFromImage(pixels));}finally{resized?.Dispose();}}
